.summary {
  &__header {
    margin: var(--space-6) 0 var(--space-4);
  }

  &__heading {
    margin: 0;
    color: var(--color-brand);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }

    @media (min-width: 768px) {
      font-size: 32px;
    }
  }

  /* Acceptance and CTA: centred, max 360px, at least 24px of air above (Gate 2). */
  &__accept {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
    width: 100%;
    max-width: 360px;
    margin-top: var(--space-8);
  }

  &__pay {
    width: 100%;
  }

  &__spinner {
    width: 18px;
    height: 18px;
    border: 3px solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: summary-spin 0.8s linear infinite;
  }

  /* States */
  &__skeleton {
    padding-top: var(--space-2);
  }

  &__skeleton-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
    padding: var(--space-6) var(--space-4);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    background: var(--color-surface);
  }

  &__skeleton-line {
    display: block;
    height: 14px;
    border-radius: var(--radius-sm);
    background: var(--color-surface-field-focus);
    animation: summary-pulse 1.4s ease-in-out infinite;

    &--title {
      width: 40%;
      height: 20px;
    }

    &--price {
      width: 50%;
      height: 32px;
    }
  }

  &__error {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    align-items: flex-start;
    padding: var(--space-4);
    border: 1px solid var(--color-error);
    border-radius: var(--radius-sm);
    background: var(--color-error-bg);
    color: var(--color-error);
    font-weight: 500;

    p {
      margin: 0;
    }
  }

  &__error-title {
    display: flex;
    align-items: center;
    gap: var(--space-2);
  }

  &__error-hint {
    color: var(--color-text-muted);
    font-weight: 400;
  }

  /* Same load animation as step 1: first render only, one item after another. */
  &__reveal {
    animation: summary-reveal 600ms cubic-bezier(0.2, 0.7, 0.2, 1) backwards;
    animation-delay: calc(var(--reveal-index, 0) * 110ms);
  }
}

/* Summary block recipe (ui-ux-guidelines §3). */
.summary-section {
  height: 100%;
  padding: var(--space-4) var(--space-6) var(--space-6);
  border-radius: 14px;
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);

  &--plan {
    box-shadow: inset 0 0 0 1px var(--color-brand);
  }

  &__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-3);
    margin-bottom: var(--space-3);
  }

  &__title {
    margin: 0;
    color: var(--color-action);
    font-size: 18px;
    font-weight: 700;
  }

  &__action {
    flex: none;
    padding: var(--space-2) var(--space-4);
  }

  &__rows {
    margin: 0;
  }

  &__row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-1) var(--space-4);
    padding: var(--space-2) 0;
  }

  &__label {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__value {
    margin: 0;
    font-weight: 500;
    text-align: right;
    overflow-wrap: anywhere;
  }

  &__plan-name {
    margin: 0 0 var(--space-1);
    color: var(--color-text);
    font-size: 20px;
    font-weight: 700;
  }

  &__plan-description {
    margin: 0;
    color: var(--color-text-muted);
  }

  &__divider {
    margin: var(--space-4) 0;
    border: 0;
    border-top: 1px solid var(--color-border);
  }

  &__price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-2);
    margin: 0;
  }

  &__amount {
    color: var(--color-brand);
    font-size: 30px;
    font-weight: 700;
    line-height: 1.2;
  }

  &__period {
    color: var(--color-text-muted);
    font-size: 16px;
    font-weight: 500;
  }
}

/* Checkbox recipe: a native input drawn as a 24px box inside a 48px hit area. */
.checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-2);

  &__control {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    margin-left: calc(-1 * var(--space-3));
  }

  &__input {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    opacity: 0;
    cursor: pointer;

    &:disabled {
      cursor: not-allowed;
    }
  }

  &__box {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 7px;
    background: var(--color-surface);
    box-shadow: inset 0 0 0 2px var(--color-text-muted);
    color: transparent;
    pointer-events: none;
  }

  &__input:checked + &__box {
    background: var(--color-action);
    box-shadow: inset 0 0 0 2px var(--color-action);
    color: var(--color-surface);
  }

  &__input:focus-visible + &__box {
    box-shadow:
      inset 0 0 0 2px var(--color-text-muted),
      var(--focus-ring);
  }

  &__input:checked:focus-visible + &__box {
    box-shadow:
