/* Receipt recipe (ui-ux-guidelines §3, US-03 Gate 2 option B). */
.receipt {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  width: 100%;
  max-width: 360px;
  margin-top: var(--space-6);
  padding: var(--space-6);
  border: 1.5px dashed var(--color-border);
  border-radius: 14px;
  background: var(--color-surface);

  &__head {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-2);
    text-align: center;
  }

  &__icon {
    color: var(--color-success);
  }

  &__heading {
    margin: 0;
    color: var(--color-success);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }
  }

  &__rows {
    margin: 0;
  }

  &__row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-1) var(--space-4);
    padding: var(--space-2) 0;
    border-bottom: 1px solid var(--color-border);

    &:last-child {
      border-bottom: 0;
    }
  }

  &__label {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__value {
    margin: 0;
    font-weight: 500;
    text-align: right;
    overflow-wrap: anywhere;

    &--strong {
      font-weight: 700;
    }
  }

  &__cta {
    width: 100%;
  }
}

/* Same load animation as the other steps: first render only. */
.confirmation__reveal {
  animation: confirmation-reveal 600ms cubic-bezier(0.2, 0.7, 0.2, 1) backwards;
  animation-delay: calc(var(--reveal-index, 0) * 110ms);
}

@keyframes confirmation-reveal {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .confirmation__reveal {
    animation: none;
  }
}

