export type FieldType = 'text' | 'number' | 'select' | 'date' | 'checkbox';
export interface NamedRule {
  name: string;
  value: number | null;
}
export interface FieldRules {
  type: FieldType;
  required: boolean;
  min: number | null;
  max: number | null;
  pattern: string | null;
  validators: NamedRule[];
}
export type FieldValue = string | boolean;
export interface ValidationContext {
  legalAge: number;
  today: Date;
}
export const INVALID_ERROR = 'invalid';
/** Typing limits configured per field in the CMS (US-01 FR-015, ADR 0004). */
export type AllowedCharacters = 'digits' | 'alphanumeric' | 'rut';

export interface InputLimits {
  allowedCharacters: AllowedCharacters | null;
  maxLength: number | null;
}

export const NO_INPUT_LIMITS: InputLimits = { allowedCharacters: null, maxLength: null };

const CHARSETS: Record<AllowedCharacters, RegExp> = {
  digits: /[0-9]/,
  alphanumeric: /[A-Za-z0-9]/,
  rut: /[0-9kK.-]/,
};

export function isAllowedCharacters(value: unknown): value is AllowedCharacters {
  return typeof value === 'string' && Object.hasOwn(CHARSETS, value);
}

import type { FormFieldDescriptor, FormSections } from '../quote-form/data/form-field.model';
import { buildSummaryRows } from './summary-rows';

function field(overrides: Partial<FormFieldDescriptor> & { key: string }): FormFieldDescriptor {
  return {
    label: overrides.key,
    type: 'text',
    required: false,
    helpText: null,
    placeholder: null,
    errorMessage: '',
    order: 1,
    section: 'policyholder',
    options: [],
    rules: { type: 'text', required: false, min: null, max: null, pattern: null, validators: [] },
    inputLimits: { allowedCharacters: null, maxLength: null },
    maskedInSummary: false,
    ...overrides,
  };
}

describe('US-03 · FR-001 summary rows from the configured fields', () => {
  const fields: FormSections = {
    policyholder: [
      field({ key: 'name', label: 'Nombre', required: true }),
      field({ key: 'documentNumber', label: 'Documento', maskedInSummary: true }),
      field({ key: 'birthDate', label: 'Nacimiento', type: 'date' }),
      field({
        key: 'docType',
        label: 'Tipo',
        type: 'select',
        options: [{ label: 'Cédula', value: 'cc' }],
      }),
      field({ key: 'nickname', label: 'Apodo' }),
    ],
    vehicle: [
      field({ key: 'plate', label: 'Placa', section: 'vehicle' }),
      field({ key: 'gas', label: 'Gas', section: 'vehicle', type: 'checkbox' }),
    ],
  };
